// Второй телефон (Pixel 6 по кабелю, adb) для тестов, где камера — iPhone (Appium). Нужны BANCI_MONITORING=1 и BANCI_ANDROID_SERIAL.
// Селекторы Android (текст/content-desc через uiautomator dump) по устройству не сверены.
import { skip } from './appium.mjs';
import { requireMonitoringOptIn } from './monitoring.mjs';
import { Android, ANDROID_PACKAGE, sh } from '../android/lib.mjs';

export const HEADER_ACTIVE = 'הניטור פעיל';
export const HEADER_NOT_TRACKED = 'הבריכה לא במעקב';
export const RECENT = 'ניטורים אחרונים';
// Строка «ניטורים אחרונים»: «היום, 18:23 · 17 דק׳ · התרעה אחת» (Figma 06.1).
const ROW = /\d{1,2}:\d{2}\s*·/;

/** Разрешение на мониторинг + второй телефон по adb; иначе пропуск. */
export async function requireSecondPhone() {
  requireMonitoringOptIn();
  if (!process.env.BANCI_ANDROID_SERIAL) skip('нужен второй телефон (Pixel по кабелю): BANCI_ANDROID_SERIAL — серийник из ~/.qa-tester/devices.md');
  return Android.start();
}

/** Pixel: перезапуск приложения → «בית». */
export async function pixelHome(pixel) {
  await pixel.restart();
  await pixel.waitFor('בית', { timeout: 30000, what: 'Pixel: главный экран «בית» (не залогинен? войти вручную)' });
  await pixel.waitFor(RECENT, { timeout: 20000, what: 'Pixel: блок «ניטורים אחרונים» на «בית»' });
}

/** Pixel: свернуть приложение (Home) и вернуть его на передний план без перезапуска. */
export const pixelBackground = (pixel) => sh('input keyevent KEYCODE_HOME');
export const pixelForeground = () => sh(`monkey -p ${ANDROID_PACKAGE} -c android.intent.category.LAUNCHER 1`);

/** Строки списка «ניטורים אחרונים» на экране Pixel сверху вниз (самая новая — первая). */
export async function recentRows(pixel) {
  const out = [];
  for (const n of await pixel.dump()) {
    for (const v of [n.text, n.desc]) if (v && ROW.test(v) && !out.includes(v.trim())) out.push(v.trim());
  }
  return out;
}

/** Ждёт строку, которой не было в before; возвращает { rows, row, sec } — sec с момента вызова. Опрос результата, без пауз. */
export async function waitNewRow(pixel, before, { timeoutSec = Number(process.env.BANCI_RECENT_SEC || 15) } = {}) {
  const t0 = Date.now();
  let rows = [];
  while (Date.now() - t0 < timeoutSec * 1000) {
    rows = await recentRows(pixel).catch(() => []);
    const fresh = rows.find((r) => !before.includes(r));
    if (fresh) return { rows, row: fresh, sec: (Date.now() - t0) / 1000 };
  }
  throw new Error(`Проверка не прошла: на втором телефоне в «ניטורים אחרונים» не появилась новая строка за ${timeoutSec} с (было: ${before.slice(0, 3).join(' | ') || 'пусто'}; сейчас: ${rows.slice(0, 3).join(' | ') || 'пусто'})`);
}
